+                return (1 / y == Double.NEGATIVE_INFINITY) ? -0.0 : 0.0;
+            }
+            if (x == Double.POSITIVE_INFINITY) {
+                if (y == Double.POSITIVE_INFINITY) {
+                    return Math.PI / 4;
+                } else if (y == Double.NEGATIVE_INFINITY) {
+                    return -Math.PI / 4;
+                } else if (y > 0.0) {
+                    return 0.0;
+                } else if (y < 0.0) {
+                    return -0.0;
+                } else {
+                    return Double.NaN;
+                }
+            } else {
+                return FastMath.atan(y / x);
+            }
+        } else if (x < 0.0) {
+            if (y == 0.0) {
+                return (1 / y == Double.NEGATIVE_INFINITY) ? -Math.PI : Math.PI;
+            }
+            if (x == Double.NEGATIVE_INFINITY) {
+                if (y == Double.POSITIVE_INFINITY) {
+                    return 3 * Math.PI / 4;
+                } else if (y == Double.NEGATIVE_INFINITY) {
+                    return -3 * Math.PI / 4;
+                } else if (y > 0.0) {
+                    return Math.PI;
+                } else if (y < 0.0) {
+                    return -Math.PI;
+                } else {
+                    return Double.NaN;
+                }
+            } else if (y > 0.0) {
+                return Math.PI / 2 + FastMath.atan(-x / y);
+            } else if (y < 0.0) {
+                return -Math.PI / 2 - FastMath.atan(x / y);
+            } else {
+                return Double.NaN;
+            }
+        } else if (x == 0.0) {
+            if (y == 0.0) {
