+                    return (1 / y == Double.NEGATIVE_INFINITY) ? -Math.PI : Math.PI;
+                } else {
+                    return (1 / y == Double.NEGATIVE_INFINITY) ? -0.0 : 0.0;
+                }
+            }
+            if (y > 0.0) {
+                return Math.PI / 2;
+            } else if (y < 0.0) {
+                return -Math.PI / 2;
+            } else {
+                return Double.NaN;
+            }
+        } else {
+            return Double.NaN;
+        }
+    }
