+            asinDer4DivF4Tab[i] = ((5 + 2 * x * (2 + x * (5 - 2 * x))) * oneMinusXSqInv3_5) * ONE_DIV_F4;
+        }
+
+        for (int i = 0; i < ASIN_POWTABS_SIZE; i++) {
